package it.polimi.ingws.gc8.Client;

/**
 * Listener interface for events generated by the View.
 *
 * This interface facilitates decoupling between the View and the networking layer.
 * When a user performs an action (e.g., placing a totem, picking a card), the View
 * notifies all registered listeners via {@link #updateFromView(Object)}.
 * In a standard client-server configuration, the primary listener is the
 * {@link ClientController}, which marshals and forwards the message to the server.
 *
 * The message payload is typically a {@code PlayerAction} subclass, but it is
 * passed as an {@code Object} to maintain a strict separation of concerns,
 * keeping the View agnostic of domain-specific server-side classes.
 */
public interface ViewListener {

    /**
     * Invoked by the View when user input is captured and requires
     * transmission to the server.
     *
     * @param message the action payload, typically an instance of {@code PlayerAction}.
     */
    void updateFromView(Object message);
}